# Test generated by chat, just to check if my functions are working
import os

from dotenv import load_dotenv
from pymongo import MongoClient


load_dotenv()

MONGODB_URI = os.getenv("MONGODB_URI")
DATABASE_NAME = os.getenv("MONGODB_DATABASE")

client = MongoClient(MONGODB_URI)
db = client[DATABASE_NAME]


EXPECTED_COLLECTIONS = {
    "movie_features",
    "user_tags",
    "user_activity_logs",
    "recommendations"
}


def check_connection():
    try:
        client.admin.command("ping")
        print("[PASS] MongoDB connection")
        return True

    except Exception as error:
        print("[FAIL] MongoDB connection")
        print(error)
        return False


def check_collections():

    collections = set(db.list_collection_names())

    missing = EXPECTED_COLLECTIONS - collections

    if not missing:
        print("[PASS] Required collections exist")
        return True

    print(
        f"[FAIL] Missing collections: "
        f"{', '.join(missing)}"
    )

    return False


def check_movie_count():

    count = db.movie_features.count_documents({})

    if count == 4803:
        print(
            "[PASS] movie_features contains "
            "4803 documents"
        )
        return True

    print(
        f"[FAIL] Expected 4803 movie documents, "
        f"found {count}"
    )

    return False


def check_unique_movie_ids():

    total_documents = (
        db.movie_features.count_documents({})
    )

    unique_movie_ids = len(
        db.movie_features.distinct("movie_id")
    )

    if total_documents == unique_movie_ids:

        print(
            "[PASS] All movie_id values are unique"
        )

        return True

    print(
        "[FAIL] Duplicate movie_id values detected"
    )

    return False


def check_movie_structure():

    movie = db.movie_features.find_one({})

    required_fields = {
        "movie_id",
        "overview",
        "keywords",
        "cast",
        "crew",
        "production_companies",
        "production_countries",
        "spoken_languages"
    }

    if movie is None:

        print(
            "[FAIL] No movie document found"
        )

        return False

    missing = required_fields - set(movie.keys())

    if not missing:

        print(
            "[PASS] movie_features document structure"
        )

        return True

    print(
        f"[FAIL] Missing movie fields: {missing}"
    )

    return False


def check_indexes():

    indexes = {
        index["name"]
        for index in db.movie_features.list_indexes()
    }

    required = {
        "_id_",
        "idx_movie_id_unique",
        "idx_keywords_name"
    }

    missing = required - indexes

    if not missing:

        print(
            "[PASS] movie_features indexes"
        )

        return True

    print(
        f"[FAIL] Missing indexes: {missing}"
    )

    return False


def check_activity_logs():

    view_count = (
        db.user_activity_logs.count_documents(
            {
                "event_type": "view_movie"
            }
        )
    )

    if view_count > 0:

        print(
            f"[PASS] Activity logs contain "
            f"{view_count} movie view event(s)"
        )

        return True

    print(
        "[FAIL] No movie view activity found"
    )

    return False


def check_recommendations():

    recommendation = (
        db.recommendations.find_one(
            {
                "algorithm":
                    "keyword_similarity"
            },
            sort=[
                ("generated_at", -1)
            ]
        )
    )

    if recommendation is None:

        print(
            "[FAIL] No recommendation "
            "document found"
        )

        return False

    recommendations = (
        recommendation.get(
            "recommendations",
            []
        )
    )

    if len(recommendations) == 10:

        print(
            "[PASS] Recommendation document "
            "contains 10 movies"
        )

        return True

    print(
        f"[FAIL] Expected 10 recommendations, "
        f"found {len(recommendations)}"
    )

    return False


if __name__ == "__main__":

    print("\nMongoDB Component Test")
    print("=" * 40)

    tests = [
        check_connection,
        check_collections,
        check_movie_count,
        check_unique_movie_ids,
        check_movie_structure,
        check_indexes,
        check_activity_logs,
        check_recommendations
    ]

    results = []

    for test in tests:

        results.append(
            test()
        )

    passed = sum(results)
    total = len(results)

    print("\n" + "=" * 40)

    print(
        f"Tests passed: {passed}/{total}"
    )

    if passed == total:

        print(
            "MongoDB setup verified successfully."
        )

    else:

        print(
            "Some MongoDB checks failed."
        )

    client.close()